  "accLinkFailed": "Povezava je morda potekla ali je bila že uporabljena. Odprite Račun, da se prijavite ali zahtevate novo sporočilo.",
  "privFooter": "Zasebnost in shramba",
  "privTitle": "Zasebnost in shramba brskalnika",
  "privClose": "Zapri obvestilo o zasebnosti",
  "privWho": "Kdo je odgovoren?",
  "privWhat": "Kaj uporabljamo in zakaj",
  "privStorage": "Shramba brskalnika",
  "privOther": "Druge obstoječe funkcije",
  "privProviders": "Ponudniki storitev in mednarodni prenosi",
  "privRetention": "Hramba in izbris",
  "privRights": "Vaše pravice",
  "noticeReopen": "Obvestilo o shrambi",
  "noticeLabel": "Obvestilo o shrambi brskalnika",
  "noticeText": "Cook uporablja shrambo brskalnika za funkcije kuhanja in prijave, ki jih uporabljate. Shramba za oglaševanje ali analitiko ni dodana.",
  "noticeClose": "Zapri obvestilo o shrambi",
  "privDraftLabel": "Osnutek — posodobljeno 28. oktobra 2026.",
  "privDraft": "Funkcije računa se trenutno preizkušajo. Spodnje podatke o upravljavcu in storitvah je treba dopolniti pred javnim zagonom.",
  "privWho1": "Cook upravlja [uradno ime in poštni naslov upravljavca]. Za vprašanja in zahteve glede zasebnosti pišite na [e-poštni naslov za zasebnost]. Te podatke je treba dopolniti, preden se odpre registracija.",
  "privWhat1": "Ko ustvarite račun, uporabimo vaš e-poštni naslov, identifikator računa, podatke o preverjanju z geslom in stanje potrditve, da vam zagotovimo in zaščitimo račun. Gesla ponudnik preverjanja pristnosti obdeluje kot varne zgoščene vrednosti; Cook ne hrani berljivih gesel. Shranjujemo razporeditev kuhinje, izbrani jezik, temo in merske enote, da obnovimo vaše nastavitve na vseh napravah. Za račun sta potrebna e-poštni naslov in geslo; recepte lahko brskate tudi brez računa.",
  "privWhat2": "Obdelava računa in nastavitev je potrebna za zagotavljanje storitve računa, ki jo zahtevate (točka (b) prvega odstavka 6. člena Splošne uredbe o varstvu podatkov). Omejeni podatki za varnost in preprečevanje zlorab se lahko obdelujejo na podlagi zakonitih interesov (točka (f) prvega odstavka 6. člena), če je to potrebno in po tehtanju interesov. Sporočila za potrditev in ponastavitev gesla so storitvena sporočila, ne trženje. Funkcija računa ne dodaja oglaševanja ali analitike.",
  "privStorage1": "Cook uporablja sessionStorage, da vašo kuhinjo, napredek kuhanja in izbire prenaša med stranmi v istem zavihku. Ko ste prijavljeni, hrani tudi vašo sejo prijave. Brskalnik to običajno izbriše, ko se seja zavihka konča, vendar jo lahko obnova seje brskalnika ohrani. Odjava izbriše Cookove podatke zavihka. Zaprtje obvestila o shrambi se zapomni samo v tem zavihku. Cookovi lastni skripti ne nastavljajo piškotkov. Vaši ponudniki gostovanja ali storitev imajo lahko lastno varnostno obdelavo, ki jo je treba pred zagonom dokumentirati.",
  "privStorage2": "V redu in gumb za zapiranje obvestila o shrambi obvestilo le zapreta. Ne dovoljujeta analitike, oglaševanja ali drugega neobveznega sledenja. Vsaka prihodnja nenujna shramba bo pred začetkom zahtevala ločeno izbiro, z enako preprosto zavrnitvijo in preklicem.",
  "privOther1": "Trenutna glasovna funkcija seznama receptov na podlagi vašega naslova IP pri country.is zahteva približno državo, da izbere jezik prepoznavanja govora. Če uporabljate prepoznavanje prek mikrofona, lahko brskalnik pošlje zvok svojemu ponudniku prepoznavanja govora. Sestavine lahko tudi vtipkate. Te ponudnike, njihove politike in pravno podlago teh funkcij je treba pregledati pred javnim zagonom.",
  "privProviders1": "Načrtovani ponudnik računov: Supabase (upravljani PostgreSQL in preverjanje pristnosti) z izbrano podatkovno regijo v EU. Ponudnik e-pošte: [ponudnik]. Gostovanje spletnega mesta: [ponudnik]. Upravljavec mora potrditi dejanske ponudnike, pogodbe o obdelavi, podobdelovalce, lokacije dnevnikov in morebitne prenose zunaj EGP. Podatkovna regija v EU sama po sebi ne izključuje mednarodnih prenosov. Kjer je ustrezno, navedite veljavni sklep o ustreznosti ali pogodbene zaščitne ukrepe in kako dobiti njihovo kopijo.",
  "privRetention1": "Nastavitve računa se hranijo, dokler je vaš račun aktiven. Izbris lahko zahtevate prek zgoraj navedenega kontakta za zasebnost. Pred zagonom mora upravljavec določiti postopek odgovarjanja na zahteve za izbris, potek nepotrjenih računov ter roke hrambe varnostnih dnevnikov in varnostnih kopij. Izbrisani podatki lahko ostanejo v varnostnih kopijah z omejenim dostopom do konca dokumentiranega roka hrambe.",
  "privRights1": "Glede na veljavne pogoje lahko zahtevate dostop, popravek, izbris, omejitev ali prenosljivost oziroma ugovarjate obdelavi na podlagi zakonitega interesa. Obrnite se na zgoraj navedenega upravljavca; na zahteve se običajno odgovori v enem mesecu, morebitno zakonito podaljšanje pa se pojasni. Pritožbo lahko vložite pri nadzornem organu, med drugim pri madžarskem NAIH na naih.hu. Cook nastavitev računa ne uporablja za avtomatizirane odločitve s pravnimi ali podobno pomembnimi učinki.",
  "favOnly": "Samo priljubljeni",
  "favAdd": "Dodaj med priljubljene",
  "favAdded": "Dodano med priljubljene",
  "favSignIn": "Prijavite se, da shranite priljubljene.",
