  "Fill the pot": "Napolnite lonec",
  "Fill the large pot with # L cold water. Don't add oil.": "Velik lonec napolnite z # l hladne vode. Olja ne dodajajte.",
  "Pot filled": "Lonec napolnjen",
  "Put it on the stove": "Postavite na štedilnik",
  "Put the pot on the largest burner, turn it to HIGH and put the lid on (it boils faster).": "Lonec postavite na največjo ploščo, nastavite na VISOKO in pokrijte s pokrovko (hitreje zavre).",
  "Lid on, burner on high": "Pokrovka gor, plošča na visoko",
  "Wait for the boil": "Počakajte, da zavre",
  "Let the water come to a full rolling boil. Meanwhile, start the prep.": "Pustite, da voda močno zavre. Medtem začnite s pripravo.",
  "Big bubbles break the surface all the time": "Veliki mehurčki ves čas pokajo na površini",
  "Eggs out of the fridge": "Jajca iz hladilnika",
  "Take the eggs out of the fridge so they warm up.": "Jajca vzemite iz hladilnika, da se ogrejejo.",
  "Eggs on the counter": "Jajca na pultu",
  "Dice the guanciale": "Narežite guanciale na kocke",
